ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm = file->private_data;
    ssize_t bytes_read = 0;
    char *tmp_page;
    int ret = 0;

    if (!mm || !mm->env_size)
        return -EINVAL;

    tmp_page = (char *)__get_free_page(GFP_KERNEL);
    if (!tmp_page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (bytes_read < count && *ppos < mm->env_size) {
        size_t chunk_size = min(count - bytes_read, PAGE_SIZE);
        void *env_data = mm->env + *ppos;

        if (copy_from_user(tmp_page, env_data, chunk_size)) {
            ret = -EFAULT;
            break;
        }

        if (copy_to_user(buf + bytes_read, tmp_page, chunk_size)) {
            ret = -EFAULT;
            break;
        }

        *ppos += chunk_size;
        bytes_read += chunk_size;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)tmp_page);

    return ret ? ret : bytes_read;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_mapping->private_data;
    ssize_t total_read = 0;
    char *page;
    size_t offset = 0;
    int ret;

    if (!mm || !mm->env_size)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    while (total_read < count) {
        size_t bytes_to_read = min(count - total_read, PAGE_SIZE);

        ret = access_process_vm(mm, *ppos + offset, page, bytes_to_read, FOLL_FORCE);
        if (ret <= 0)
            break;

        if (copy_to_user(buf + total_read, page, ret)) {
            ret = -EFAULT;
            break;
        }

        total_read += ret;
        offset += ret;

        if (ret < bytes_to_read)
            break;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);

    if (total_read > 0)
        *ppos += total_read;

    return total_read ? total_read : ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_mapping->host->mm;
    ssize_t ret = 0;
