    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);
    if (!mm->env_size) {
        ret = 0;
        goto out_unlock;
    }

    while (count > 0) {
        size_t len = min(count, PAGE_SIZE);
        size_t env_len;

        env_len = copy_strings_from_tsk(page, mm, 0, NULL);
        if (env_len == 0)
            break;

        len = min(len, env_len);
        if (copy_to_user(buf, page, len)) {
            ret = -EFAULT;
            break;
        }

        buf += len;
        count -= len;
        *ppos += len;
        ret += len;
    }

out_unlock:
    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    return ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct mm_struct *mm = file->f_mapping->host->mm;
    ssize_t ret = 0;
    char *page;
    size_t env_size;
    size_t pos = (size_t)*ppos;
    size_t env_bytes_read = 0;
    size_t bytes_to_read;
    char *env_start;
    int i = 0;

    if (!mm)
        return -EFAULT;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);

    env_start = mm->env_start;
    env_size = mm->env_size;

    if (!env_start || !env_size) {
        ret = 0;
        goto out;
    }

    while (env_bytes_read < env_size && ret < count) {
        bytes_to_read = min(count - ret, (size_t)(PAGE_SIZE - (pos % PAGE_SIZE)));
        bytes_to_read = min(bytes_to_read, (size_t)(env_size - env_bytes_read));

        if (copy_from_user(page, env_start + pos, bytes_to_read)) {
            ret = -EFAULT;
            goto out;
        }

        if (copy_to_user(buf + ret, page, bytes_to_read)) {
            ret = -EFAULT;
            goto out;
        }

        ret += bytes_to_read;
        pos += bytes_to_read;
        env_bytes_read += bytes_to_read;
    }

    *ppos = pos;

out:
    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);

    return ret;
}

ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_inode->i_private;
    ssize_t total_read = 0;
    unsigned long pos = *ppos;
    char *page;
    int ret;

    if (!mm)
        return -EINVAL;

    page = (char *)__get_free_page(GFP_KERNEL);
    if (!page)
        return -ENOMEM;

    down_read(&mm->mmap_lock);
    while (pos < mm->env_size && total_read < count) {
        ret = get_user_pages_unlocked(current, mm, pos, 1, 0, &page, NULL);
        if (ret <= 0) {
            total_read = ret;
            break;
        }

        size_t remaining = mm->env_size - pos;
        size_t to_copy = min(remaining, count - total_read);
        if (copy_to_user(buf + total_read, page, to_copy)) {
            total_read = -EFAULT;
            break;
        }

        total_read += to_copy;
        pos += to_copy;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    *ppos = pos;
    return total_read;
}
